pub type AsyncMutex<T> = tokio::sync::Mutex<T>;

/// The app this bridge is built into: the iOS app links the same crate.
#[cfg(target_os = "ios")]
const PLATFORM: Platform = Platform::Ios {};
#[cfg(not(target_os = "ios"))]
const PLATFORM: Platform = Platform::Android {};

uniffi::setup_scaffolding!();
uniffi::use_remote_type!(beep_proto::ReasoningLevel);

const CONNECT_TIMEOUT: Duration = Duration::from_secs(20);
const CALL_TIMEOUT: Duration = Duration::from_secs(45);

/// Field names avoid `message`, which Kotlin exceptions already define.
#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum BeepError {
    #[error("{reason}")]
    BadRequest { reason: String },
    #[error("not found")]
    NotFound,
    #[error("{reason}")]
    Conflict { reason: String },
    #[error("unauthorized")]
    Unauthorized,
    #[error("server error")]
    Internal,
    #[error("{reason}")]
    Connection { reason: String },
}

impl From<ApiError> for BeepError {
    fn from(e: ApiError) -> Self {
        match e {
            ApiError::BadRequest { message } => Self::BadRequest { reason: message },
            ApiError::NotFound {} => Self::NotFound,
            ApiError::Conflict { message } => Self::Conflict { reason: message },
            ApiError::Unauthorized {} => Self::Unauthorized,
            ApiError::Internal {} => Self::Internal,
        }
    }
}

impl From<anyhow::Error> for BeepError {
    fn from(e: anyhow::Error) -> Self {
        match e.downcast::<ApiError>() {
            Ok(api) => api.into(),
            Err(e) => Self::Connection {
                reason: format!("{e:#}"),
            },
        }
    }
}

fn io_error(error: io::Error) -> BeepError {
    BeepError::Connection {
        reason: format!("could not save the file: {error}"),
    }
}

fn bad_request(message: impl Into<String>) -> BeepError {
    BeepError::BadRequest {
        reason: message.into(),
    }
}

async fn timed<T>(
    limit: Duration,
    what: &str,
    fut: impl Future<Output = anyhow::Result<T>>,
) -> Result<T, BeepError> {
    match timeout(limit, fut).await {
        Ok(result) => Ok(result?),
        Err(_) => Err(BeepError::Connection {
            reason: format!("{what} timed out"),
        }),
    }
}

fn uuid(text: &str) -> Result<Uuid, BeepError> {
    Uuid::parse_str(text).map_err(|_| bad_request("invalid UUID"))
}

/// Writes the file `fetch` returns from each offset to `path`. It lands
/// under a temporary name first, so `path` never holds half a file, and the
/// temporary file is removed when anything fails.
async fn download<F, Fut>(path: &str, fetch: F) -> Result<u64, BeepError>
where
    F: FnMut(u64) -> Fut,
    Fut: Future<Output = Result<FilePart, BeepError>>,
{
    let partial = format!("{path}.part");
    let result = download_to(&partial, path, fetch).await;
    if result.is_err() {
        // It may never have been created, and the first error matters more.
        let _ = fs::remove_file(&partial).await;
    }
    result
}

async fn download_to<F, Fut>(partial: &str, path: &str, mut fetch: F) -> Result<u64, BeepError>
where
    F: FnMut(u64) -> Fut,
    Fut: Future<Output = Result<FilePart, BeepError>>,
{
    let mut file = fs::File::create(partial).await.map_err(io_error)?;
    let mut offset = 0;
    loop {
        let part = fetch(offset).await?;
        file.write_all(&part.data).await.map_err(io_error)?;
        offset += part.data.len() as u64;
        if offset >= part.size || part.data.is_empty() {
            break;
        }
    }
    file.flush().await.map_err(io_error)?;
    drop(file);
    fs::rename(partial, path).await.map_err(io_error)?;
    Ok(offset)
}

fn secret_key(bytes: &[u8]) -> Result<SecretKey, BeepError> {
    let bytes: &[u8; 32] = bytes
        .try_into()
        .map_err(|_| bad_request("an identity is 32 bytes"))?;
    Ok(SecretKey::from_bytes(bytes))
}

/// A new random identity, as `BeepClient::new` takes it.
#[uniffi::export]
pub fn new_identity() -> Vec<u8> {
    SecretKey::generate().to_bytes().to_vec()
}

/// The settings lists the phone last fetched, kept to show at once while it
/// fetches them again. A list is `None` until the phone first fetched it.
#[derive(uniffi::Record, Serialize, Deserialize, Default)]
pub struct ListCache {
    pub memories: Option<Vec<Memory>>,
    pub crons: Option<Vec<Cron>>,
    pub apps: Option<Vec<AppIntegration>>,
    pub models: Option<Models>,
}

/// `cache` as bytes for the phone to save.
#[uniffi::export]
pub fn encode_list_cache(cache: ListCache) -> Vec<u8> {
    // Plain records and lists, which msgpack always encodes.
    rmp_serde::to_vec(&cache).unwrap_or_default()
}

/// The cache `encode_list_cache` saved, or an empty one when it was saved
/// by a build whose records differ.
#[uniffi::export]
pub fn decode_list_cache(bytes: Vec<u8>) -> ListCache {
    rmp_serde::from_slice(&bytes).unwrap_or_default()
}

/// The notice the server sealed to this phone and sent through Firebase.
#[uniffi::export]
pub fn open_notice(identity: Vec<u8>, sealed: String) -> Result<Notice, BeepError> {
    Ok(seal::open(&secret_key(&identity)?, &sealed)?)
}

/// An admin's one-off pick for a single turn, as Rerun sends it.
#[derive(uniffi::Record)]
pub struct Rerun {
    /// A `ModelChoice::id`.
    pub model: String,
    /// None keeps the admin's picked thinking.
    pub thinking: Option<ReasoningLevel>,
}

/// What a scanned link code asks for, shown before the phone links it.
#[derive(uniffi::Record)]
pub struct LinkPreview {
    pub name: String,
    /// The code the computer's window shows too, such as `7K4 PQ2`.
    pub code: String,
}

/// Reads a scanned or pasted link code without sending it anywhere.
#[uniffi::export]
pub fn link_preview(offer_uri: String) -> Result<LinkPreview, BeepError> {
    let offer = LinkOffer::parse(&offer_uri).map_err(|e| bad_request(e.to_string()))?;
    Ok(LinkPreview {
        code: offer.code(),
        name: offer.name,
    })
}

